export declare const MEDIA_CSS = "\n/* image view */\n.dr-image {\n    position: relative;\n    display: block;\n    overflow: hidden;\n    min-height: 0;\n    background: var(--scene-bg, var(--bg));\n}\n.dr-image__media {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: contain;\n}\n.dr-image--cover .dr-image__media { object-fit: cover; }\n.dr-image__overlay { pointer-events: none; }\n.dr-image__media[data-quality=\"low\"] { filter: blur(0.4px); opacity: 0.85; }\n.dr-image__waiting {\n    position: absolute;\n    inset: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--muted-fg);\n    opacity: 0.6;\n}\n\n/* playback bar */\n.dr-playback {\n    display: flex;\n    flex-direction: column;\n    min-width: 0;\n    background: var(--surface);\n    border-top: 1px solid var(--border);\n    color: var(--fg);\n}\n.dr-playback__bar {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 8px 12px;\n    min-width: 0;\n}\n.dr-playback__controls {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    flex: none;\n}\n.dr-playback__time {\n    font: 12px var(--mono);\n    font-variant-numeric: tabular-nums;\n    white-space: nowrap;\n}\n.dr-playback__now { color: var(--fg); }\n.dr-playback__length { color: var(--muted-fg); }\n.dr-playback__speed { width: auto; }\n.dr-playback__expand {\n    appearance: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n    height: 28px;\n    padding: 0 8px;\n    font: 500 12px var(--sans);\n    color: var(--muted-fg);\n    background: transparent;\n    border: 1px solid transparent;\n    border-radius: var(--radius);\n    cursor: pointer;\n}\n.dr-playback__expand:hover { color: var(--fg); background: var(--hover); }\n.dr-playback__expand:focus-visible { outline: none; box-shadow: var(--dr-focus); }\n.dr-playback__on,\n.dr-playback__on:hover { color: var(--primary); background: var(--sel); }\n.dr-playback__lane {\n    position: relative;\n    flex: 1;\n    min-width: 0;\n    height: 28px;\n    cursor: pointer;\n    touch-action: none;\n}\n.dr-playback__thumb--active { transform: scale(1.25); }\n.dr-playback__hover,\n.dr-playback__window {\n    position: absolute;\n    top: -16px;\n    font: 10.5px var(--mono);\n    color: var(--muted-fg);\n    pointer-events: none;\n    white-space: nowrap;\n}\n.dr-playback__hover { transform: translateX(-50%); color: var(--fg); }\n.dr-playback__window { right: 0; }\n.dr-playback__rows {\n    display: flex;\n    flex-direction: column;\n    max-height: min(40vh, 360px);\n    overflow-y: auto;\n    border-top: 1px solid var(--hair);\n}\n.dr-playback__row {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 0 12px;\n    min-height: 30px;\n    border-bottom: 1px solid var(--hair);\n}\n.dr-playback__row--busy { opacity: 0.5; pointer-events: none; }\n.dr-playback__name {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    flex: none;\n    width: min(40%, 340px);\n    min-width: 0;\n}\n.dr-playback__leading { width: 28px; flex: none; }\n.dr-playback__label {\n    flex: 1;\n    min-width: 0;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    font: 12px var(--mono);\n    color: var(--muted-fg);\n}\n.dr-playback__row--active .dr-playback__label { color: var(--fg); }\n.dr-playback__meta,\n.dr-playback__count {\n    flex: none;\n    font: 11px var(--mono);\n    color: var(--muted-fg);\n    white-space: nowrap;\n}\n.dr-playback__row .dr-playback__lane { height: 22px; }\n.dr-playback__ticks {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    color: var(--muted-fg);\n}\n.dr-playback__row--active .dr-playback__ticks { color: var(--primary); }\n.dr-playback__cursor {\n    position: absolute;\n    top: 0;\n    bottom: 0;\n    width: 1px;\n    background: var(--primary);\n    pointer-events: none;\n}\n@media (max-width: 700px) {\n    .dr-playback__bar { flex-wrap: wrap; }\n    .dr-playback__track { flex-basis: 100%; }\n    .dr-playback__name { width: 45%; }\n}\n";
